package com.ali.nothingrail;
import android.appwidget.*;import android.content.*;import android.net.*;import android.widget.*;import java.io.*;import java.net.*;import org.json.*;import java.text.*;import java.util.*;
public class RailWidget extends AppWidgetProvider{static final String A="com.ali.nothingrail.REFRESH";public void onUpdate(Context c,AppWidgetManager m,int[] ids){for(int id:ids)render(c,m,id);}public void onReceive(Context c,Intent i){super.onReceive(c,i);if(A.equals(i.getAction()))refresh(c);}static void render(Context c,AppWidgetManager m,int id){RemoteViews v=new RemoteViews(c.getPackageName(),R.layout.widget);String t=c.getSharedPreferences("rail",0).getString("train","");v.setTextViewText(R.id.trainNo,t.isEmpty()?"----":t);v.setTextViewText(R.id.trainName,"INDIAN RAILWAYS");v.setTextViewText(R.id.location,t.isEmpty()?"Configure train":"Fetching status…");v.setTextViewText(R.id.detail,t.isEmpty()?"Tap to configure":"Tap ↻ to refresh");v.setTextViewText(R.id.status,"READY");Intent a=new Intent(c,MainActivity.class);v.setOnClickPendingIntent(R.id.root,PendingIntent.getActivity(c,0,a,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE));Intent r=new Intent(c,RailWidget.class).setAction(A);v.setOnClickPendingIntent(R.id.refresh,PendingIntent.getBroadcast(c,id,r,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE));m.updateAppWidget(id,v);if(!t.isEmpty())new Thread(()->fetch(c,m,id,t)).start();}static void fetch(Context c,AppWidgetManager m,int id,String t){String b=c.getSharedPreferences("rail",0).getString("base","").trim();if(b.isEmpty()){set(c,m,id,"NO LIVE API","Add API base URL","CONFIG REQUIRED");return;}try{URL u=new URL(b.replaceAll("/$","")+"/trains/getTrain?trainNo="+Uri.encode(t));HttpURLConnection x=(HttpURLConnection)u.openConnection();x.setConnectTimeout(8000);x.setReadTimeout(10000);BufferedReader z=new BufferedReader(new InputStreamReader(x.getInputStream()));StringBuilder s=new StringBuilder();String l;while((l=z.readLine())!=null)s.append(l);JSONObject o=new JSONObject(s.toString());String n=o.optString("train_name",o.optString("name","TRAIN INFORMATION"));set(c,m,id,"DATA RECEIVED",n,"UPDATED "+new SimpleDateFormat("HH:mm",Locale.getDefault()).format(new Date()));}catch(Exception e){set(c,m,id,"LIVE UNAVAILABLE","Check API URL","RETRY ↻");}}static void set(Context c,AppWidgetManager m,int id,String l,String d,String s){RemoteViews v=new RemoteViews(c.getPackageName(),R.layout.widget);String t=c.getSharedPreferences("rail",0).getString("train","");v.setTextViewText(R.id.trainNo,t);v.setTextViewText(R.id.trainName,"INDIAN RAILWAYS");v.setTextViewText(R.id.location,l);v.setTextViewText(R.id.detail,d);v.setTextViewText(R.id.status,s);Intent r=new Intent(c,RailWidget.class).setAction(A);v.setOnClickPendingIntent(R.id.refresh,PendingIntent.getBroadcast(c,id,r,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE));m.updateAppWidget(id,v);}public static void refresh(Context c){AppWidgetManager m=AppWidgetManager.getInstance(c);for(int id:m.getAppWidgetIds(new ComponentName(c,RailWidget.class)))render(c,m,id);}}
